import subprocess
def run(inp_bytes, extra=[]):
    p=subprocess.run(["./executable","--no-gitconfig","--paging=never","--syntax-theme=none"]+extra, input=inp_bytes, capture_output=True)
    return p.stdout.decode(errors='replace')

def test_n(n, extra=[]):
    minus = [f"line {i} foo" for i in range(n)]
    plus = [f"line {i} FOO" for i in range(n)]
    hunk = "".join([f"-{l}\n" for l in minus] + [f"+{l}\n" for l in plus])
    inp=f"diff --git a/f.txt b/f.txt\n--- a/f.txt\n+++ b/f.txt\n@@ -1,{n} +1,{n} @@\n{hunk}".encode()
    out=run(inp, extra)
    lines=out.splitlines()
    m_lines=[l for l in lines if "48;5;52" in l or "48;5;124" in l]
    p_lines=[l for l in lines if "48;5;22" in l or "48;5;28" in l]
    m_emph=sum(1 for l in m_lines if "48;5;124" in l)
    p_emph=sum(1 for l in p_lines if "48;5;28" in l)
    print(f"n={n} extra={extra} m_emph={m_emph} p_emph={p_emph}")
    # For large n, show which indices paired?
    if n>=60:
        import re
        for idx,l in enumerate(m_lines):
            if "48;5;124" in l:
                clean=re.sub(r'\x1b\[[0-9;]*m','',l)
                print(f"  m paired idx {idx} clean {repr(clean[:30])}")
        for idx,l in enumerate(p_lines):
            if "48;5;28" in l:
                clean=re.sub(r'\x1b\[[0-9;]*m','',l)
                print(f"  p paired idx {idx} clean {repr(clean[:30])}")

